<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getMeterContext } from './meter-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const meter = getMeterContext();</script><div bind:this={ref} {...rest} style:--meter-value={`${meter.percentage}%`} data-value={meter.value}>{@render children?.()}</div>
